object CollectionsDemo extends App {
  val numbers = List(1, 2, 3, 4, 5, 6)

  // Loc so chan va gap doi gia tri
  val evenDoubled = numbers.filter(_ % 2 == 0).map(_ * 2)
  println(s"Ket qua: $evenDoubled") // List(4, 8, 12)

  // Tinh tong danh sach bang reduce
  val total = numbers.reduce(_ + _)
  println(s"Tong: $total") // 21
}

// Dinh nghia Case Class
case class User(name: String, role: String, age: Int)

object Main extends App {
  val u = User("Minh", "Admin", 25)

  // Pattern Matching theo kieu du lieu va gia tri
  u match {
    case User(name, "Admin", _) => println(s"Xin chao quan tri vien $name!")
    case User(name, _, age) if age < 18 => println(s"Chao ban tre $name")
    case _ => println("Nguoi dung tieu chuan")
  }
}

object OptionDemo extends App {
  def findUser(id: Int): Option[String] = {
    if (id == 1) Some("Nguyen Van A") else None
  }

  val userName = findUser(1).getOrElse("Khong tim thay nguoi dung")
  println(userName)
}

import scala.concurrent.{Future, Await}
import scala.concurrent.ExecutionContext.Implicits.global
import scala.concurrent.duration._

object FutureDemo extends App {
  val f = Future {
    Thread.sleep(500)
    42
  }

  val mapped = f.map(_ * 2)
  val result = Await.result(mapped, 2.seconds)
  println(s"Ket qua bat dong bo: $result") // 84
}

